/**
 * 展示层敏感数据脱敏工具（P2-3）：
 * - maskSecret：通用"中间打码"——保留首尾可见字符，中间替换为掩码。
 * - maskShareUrl：分享链接脱敏——只对最后一段路径（shareToken）打码，
 *   协议/主机/前缀保持不变，便于用户辨认链接但无法一眼读出完整 token。
 * 设计口径：
 *   - 空值返回空串；过短输入全部打码（不泄露长度之外的信息）。
 *   - 默认可见位数 4/3（token 通常 ≥16 位，打码后仍可辨认首尾）。
 *   - 掩码固定为 4 个 *（覆盖原中间段，不保留原始长度信息）。
 */

/** 通用中间打码。 */
export function maskSecret(
  value: string | null | undefined,
  opts: { visibleStart?: number; visibleEnd?: number; mask?: string } = {},
): string {
  const { visibleStart = 4, visibleEnd = 4, mask = '****' } = opts;
  if (value == null || value === '') return '';
  if (visibleStart < 0 || visibleEnd < 0) return mask;
  // 总可见长度 ≥ 全长时也视为"不可安全脱敏"（如极短串），直接全打码
  if (value.length <= visibleStart + visibleEnd) return mask;
  return value.slice(0, visibleStart) + mask + value.slice(value.length - visibleEnd);
}

/** 分享链接脱敏：仅打码最后一段路径（shareToken）与 query 参数值。 */
export function maskShareUrl(url: string | null | undefined): string {
  if (url == null || url === '') return '';
  // 拆分 path 与 query/hash；query 参数值打码（可能携带 password 等敏感参数），hash 原样保留结构
  const [pathPart, ...rest] = url.split('?');
  const suffix = rest.length ? '?' + maskQuery(rest.join('?')) : '';
  const hashIdx = pathPart.indexOf('#');
  const pathOnly = hashIdx >= 0 ? pathPart.slice(0, hashIdx) : pathPart;
  const hash = hashIdx >= 0 ? pathPart.slice(hashIdx) : '';
  // 去掉结尾斜杠后取最后一段
  const segments = pathOnly.replace(/\/+$/, '').split('/');
  if (segments.length === 0) return maskSecret(url);
  const tokenIdx = segments.length - 1;
  segments[tokenIdx] = maskSecret(segments[tokenIdx], { visibleStart: 4, visibleEnd: 3 });
  return segments.join('/') + hash + suffix;
}

/** query 参数值打码：`a=1&b=secret` → `a=****&b=****`；无值的裸参数整段打码。 */
function maskQuery(query: string): string {
  return query
    .split('&')
    .map((part) => {
      const eq = part.indexOf('=');
      if (eq < 0) return maskSecret(part);
      return part.slice(0, eq + 1) + maskSecret(part.slice(eq + 1));
    })
    .join('&');
}
