import { maskSecret, maskShareUrl } from './mask';

describe('maskSecret（通用中间打码）', () => {
  it('空值返回空串', () => {
    expect(maskSecret(null)).toBe('');
    expect(maskSecret(undefined)).toBe('');
    expect(maskSecret('')).toBe('');
  });

  it('过短输入全部打码（不泄露长度）', () => {
    expect(maskSecret('abc')).toBe('****');
    expect(maskSecret('12345678')).toBe('****'); // 8 <= 4+4
  });

  it('正常打码保留首尾', () => {
    expect(maskSecret('abcdefghijklmnop')).toBe('abcd****mnop');
  });

  it('可自定义可见位数与掩码', () => {
    expect(maskSecret('abcdefghijk', { visibleStart: 2, visibleEnd: 2, mask: '**' })).toBe(
      'ab**jk',
    );
    expect(maskSecret('abcdefghijk', { visibleStart: 0, visibleEnd: 0, mask: '****' })).toBe(
      '****',
    );
  });
});

describe('maskShareUrl（分享链接脱敏）', () => {
  it('空值返回空串', () => {
    expect(maskShareUrl(null)).toBe('');
    expect(maskShareUrl('')).toBe('');
  });

  it('相对路径只打码 token 段', () => {
    expect(maskShareUrl('/s/dsg_muf341yew9ud6z')).toBe('/s/dsg_****d6z'); // token 段 4/3
  });

  it('完整 URL 保留协议/主机，打码最后一段', () => {
    expect(maskShareUrl('https://oos.example.com/s/dsg_muf341yew9ud6z')).toBe(
      'https://oos.example.com/s/dsg_****d6z',
    );
  });

  it('带 query 时参数值打码、key 保留', () => {
    expect(maskShareUrl('/s/dsg_muf341yew9ud6z?password=abc123')).toBe(
      '/s/dsg_****d6z?password=****',
    );
  });

  it('多参数各自打码', () => {
    expect(maskShareUrl('/s/abcdefghijklmnop?a=1&b=secret123')).toBe(
      '/s/abcd****nop?a=****&b=secr****t123', // query 值 4/4
    );
  });

  it('带 hash 时保留 hash 结构', () => {
    expect(maskShareUrl('/s/dsg_muf341yew9ud6z#view')).toBe('/s/dsg_****d6z#view');
  });

  it('结尾斜杠容错', () => {
    expect(maskShareUrl('/s/dsg_muf341yew9ud6z/')).toBe('/s/dsg_****d6z');
  });
});
